WITH remaining_keys AS (SELECT browser, device FROM sessions INTERSECT SELECT browser, device FROM sessions WHERE customer_id = 5), verified AS (SELECT s.* FROM sessions s INNER JOIN remaining_keys k ON s.browser = k.browser AND s.device = k.device) SELECT s.id, s.customer_id, s.browser, s.country, CASE WHEN country RLIKE '^(US|DE)$' THEN 'OTHER_ZONE' WHEN country RLIKE '^(TH|SG)$' THEN 'EXTENDED' ELSE 'GROUP_A' END AS country_zone, (SELECT MAX(o2.discount) FROM orders o2 WHERE o2.customer_id = s.customer_id) AS max_order_discount FROM verified s ORDER BY country_zone;
